'use client';

import { useState, useEffect } from 'react';
import { useRouter } from 'next/navigation';

interface KYCFormData {
  firstName: string;
  lastName: string;
  age: number;
  tradingExperience: 'beginner' | 'intermediate' | 'advanced';
  riskTolerance: 'low' | 'moderate' | 'high';
  investmentGoals: string;
  agreeToTerms: boolean;
}

export default function KYCPage() {
  const router = useRouter();
  const [step, setStep] = useState<'intro' | 'form' | 'success'>('intro');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [formData, setFormData] = useState<KYCFormData>({
    firstName: '',
    lastName: '',
    age: 25,
    tradingExperience: 'beginner',
    riskTolerance: 'moderate',
    investmentGoals: '',
    agreeToTerms: false,
  });

  useEffect(() => {
    // Check if user is authenticated
    const token = localStorage.getItem('authToken');
    if (!token) {
      router.push('/trading-signup');
    }
  }, [router]);

  const handleFieldChange = (
    e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement | HTMLTextAreaElement>
  ) => {
    const { name, value, type } = e.target;
    setFormData(prev => ({
      ...prev,
      [name]: type === 'checkbox' ? (e.target as HTMLInputElement).checked : value,
      ...(name === 'age' && { age: parseInt(value) }),
    }));
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError(null);
    setLoading(true);

    try {
      // Validation
      if (!formData.firstName || !formData.lastName) {
        throw new Error('First and last name are required');
      }

      if (formData.age < 18) {
        throw new Error('You must be at least 18 years old');
      }

      if (!formData.investmentGoals.trim()) {
        throw new Error('Please describe your investment goals');
      }

      if (!formData.agreeToTerms) {
        throw new Error('You must agree to the terms');
      }

      const token = localStorage.getItem('authToken');
      if (!token) {
        throw new Error('Not authenticated');
      }

      const response = await fetch('/api/kyc/submit', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          Authorization: `Bearer ${token}`,
        },
        body: JSON.stringify(formData),
      });

      if (!response.ok) {
        const data = await response.json();
        throw new Error(data.error || 'KYC submission failed');
      }

      setStep('success');

      // Redirect after 3 seconds
      setTimeout(() => {
        router.push('/command-center');
      }, 3000);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An error occurred');
    } finally {
      setLoading(false);
    }
  };

  return (
    <main
      style={{
        minHeight: '100vh',
        background:
          'radial-gradient(circle at 15% 0%, rgba(90,162,255,.18), transparent 32rem), #050914',
        color: '#eef5ff',
        fontFamily: 'Arial, Helvetica, sans-serif',
        padding: '20px',
      }}
    >
      {step === 'intro' && <KYCIntroSection onNext={() => setStep('form')} />}
      {step === 'form' && (
        <KYCForm
          formData={formData}
          error={error}
          loading={loading}
          onFieldChange={handleFieldChange}
          onSubmit={handleSubmit}
          onBack={() => setStep('intro')}
        />
      )}
      {step === 'success' && <SuccessSection />}
    </main>
  );
}

